{"code": "import re

# Read the context
lines = context.strip().split('\n')

# Filter out header lines
data_lines = []
for line in lines:
    if 'Date:' in line and 'User:' in line and 'Instance:' in line:
        data_lines.append(line)

print("Number of data lines:", len(data_lines))

# Parse each line
pattern = r'Date: .*?\|\|\s*User: (\d+).*?\|\|\s*Instance: (.+)$'

user_instances = {}

for line in data_lines:
    match = re.match(pattern, line)
    if match:
        user_id = int(match.group(1))
        instance_text = match.group(2).strip()
        if user_id not in user_instances:
            user_instances[user_id] = []
        user_instances[user_id].append((instance_text, line))

print("Unique users:", len(user_instances))
print("Sample users:", sorted(user_instances.keys())[:10])

# Let's check a few instances to understand the labels
print("\nSample instances:")
for user_id in list(user_instances.keys())[:5]:
    for inst_text, line in user_instances[user_id][:3]:
        print(f"User {user_id}: {inst_text[:50]}...")
"}

